package com.example.grid;

final class Grid {                       // no modifier: package-private
    private int dirty;
    void recalc(int i) { dirty = i; }
}

public final class GridAttorney {         // the only public door
    private final Grid grid = new Grid();
    public void refresh() { grid.recalc(0); }   // nothing else is granted
}

// module-info.java of the implementation module
module com.example.grid {
    exports com.example.grid.internal to com.example.helper;
}

// com.example.grid.internal/GridAttorney.java - still the narrow door
public final class GridAttorney {
    private final Grid grid = new Grid();          // package-private impl
    public void refresh() { grid.recalc(0); }      // the only granted call
}

